"use strict";

const fs = require("fs/promises");

module.exports = async function fileHandleProbe(fileName) {
  const data = "AutoJs6 FileHandle OK";
  let handle;
  try {
    handle = await fs.open(fileName, "w+");
    await handle.writeFile(data, "utf8");
    await handle.sync();
    await handle.close();
    handle = await fs.open(fileName, "r");
    const text = await handle.readFile("utf8");
    return {
      ok: text === data,
      summary: "filehandle:open/write/read/close:" + text.length,
    };
  } finally {
    if (handle) {
      await handle.close().catch(() => {});
    }
    await fs.unlink(fileName).catch(() => {});
  }
};
